import React from "react";
import { useNavigate } from "react-router-dom";
import "./ProductCard.css";

const ProductCard = ({ product }) => {
    const navigate = useNavigate();

    const handleViewDetail = () => {
        navigate(`/product/${product.id}`);
    };

    // 🌟 1. GIẢI PHÁP ĐỒNG BỘ: Tự động bắt mọi trường có thể chứa link ảnh từ API danh mục
    const getProductImage = () => {
        if (product.imageUrl) return product.imageUrl;
        if (product.image) return product.image; // Trường hợp API danh mục trả về tên trường là 'image'
        if (product.images && product.images.length > 0) {
            return typeof product.images[0] === 'string' ? product.images[0] : product.images[0].url;
        }
        return "https://images.unsplash.com/photo-1505693416388-ac5ce068fe85"; // Ảnh fallback sang xịn mịn
    };

    const displayImage = getProductImage();

    return (
        <div className="furniture-card h-100">
            {/* Badge */}
            <div className="furniture-badge">
                Collection
            </div>

            {/* Image */}
            <div className="furniture-img-container" onClick={handleViewDetail} style={{ cursor: 'pointer' }}>
                <img
                    src={displayImage}
                    alt={product.name}
                    className="furniture-image"
                    onError={(e) => {
                        e.target.onerror = null;
                        e.target.src = "https://images.unsplash.com/photo-1505693416388-ac5ce068fe85";
                    }}
                />
            </div>

            {/* Content */}
            <div className="furniture-content">
                <span className="furniture-category">
                    {product.categoryProductName || "Nội thất"}
                </span>

                <h3
                    className="furniture-title"
                    title={product.name}
                    onClick={handleViewDetail}
                    style={{ cursor: 'pointer' }}
                >
                    {product.name}
                </h3>

                <p className="furniture-description">
                    {product.description || "Thiết kế tinh tế, chất liệu cao cấp."}
                </p>

                <div className="furniture-footer">
                    <div className="furniture-price">
                        {typeof product.price === "number"
                            ? product.price.toLocaleString("vi-VN", {
                                  style: "currency",
                                  currency: "VND"
                              })
                            : product.price}
                    </div>

                    <button className="btn-furniture" onClick={handleViewDetail}>
                        Xem chi tiết
                    </button>
                </div>
            </div>
        </div>
    );
};

export default ProductCard;
